import{c as t,Q as o,j as a,m as n}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"CONF-KV: Confidence-Aware KV Cache Eviction with Mixed-Precision Storage for Long-Horizon LLM","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.24786","title":"CONF-KV: Confidence-Aware KV Cache Eviction with Mixed-Precision Storage for Long-Horizon LLM","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2605.24786,"authors":["Yubo Li","Yidi Miao"],"domains":["cs.LG"],"html":"https://arxiv.org/html/2605.24786v1","pdf_path":"pdfs/2605.24786.pdf","published_date":"2026-05-24T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-24-conf-kv-confidence-aware-kv-cache-eviction-2605-24786.md","filePath":"research/papers/2026-05-24-conf-kv-confidence-aware-kv-cache-eviction-2605-24786.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-05-24-conf-kv-confidence-aware-kv-cache-eviction-2605-24786.md"};function r(c,e,s,l,d,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="conf-kv-confidence-aware-kv-cache-eviction-with-mixed-precision-storage-for-long-horizon-llm" tabindex="-1">CONF-KV: Confidence-Aware KV Cache Eviction with Mixed-Precision Storage for Long-Horizon LLM <a class="header-anchor" href="#conf-kv-confidence-aware-kv-cache-eviction-with-mixed-precision-storage-for-long-horizon-llm" aria-label="Permalink to &quot;CONF-KV: Confidence-Aware KV Cache Eviction with Mixed-Precision Storage for Long-Horizon LLM&quot;">​</a></h1><p><strong>Authors</strong>: Yubo Li, Yidi Miao <strong>Published</strong>: May 24, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.24786" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.24786</a> · <a href="https://arxiv.org/html/2605.24786v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2605.24786 <strong>Categories</strong>: cs.LG <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.24786" target="_blank" rel="noreferrer">research/papers/pdfs/2605.24786.pdf</a> (20 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Long-horizon LLM inference turns the key--value (KV) cache into the dominant GPU memory consumer and makes per-token attention increasingly expensive. Many common eviction policies use static recency windows or historical attention, leaving unused a signal computed on every decoding step: the model&#39;s current uncertainty. We introduce CONF-KV, a KV-cache manager that converts the next-token distribution into a scalar confidence score and uses it to choose the per-step cache budget, retaining more context when the model is uncertain and pruning aggressively when it is confident. Within each budget, tokens are ranked by a composite of accumulated attention mass and recency, while a protected recent window preserves local coherence. We combine the policy with blockwise online-softmax attention, mixed FP16/INT8 storage, and a pyramidal per-layer budget variant. Across four model families and generated lengths up to 4K, CONF-KV stays near the footprint of a fixed 512-token sliding window while remaining within 1.5--2.1 perplexity points of full KV. On Needle-in-a-Haystack up to 32K tokens, CONF-KV reaches 91.4% retrieval accuracy versus 53.8% for sliding windows and 80.6% for H2O; on 75 VisualWebArena tasks it retains 95.3% of full-KV success at 2.8 times lower peak memory.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li><strong>Confidence-aware 動態 budget</strong>：將 next-token distribution 轉為純量 confidence score，模型不確定時保留更多 KV cache context；高信心時積極 evict，實現自適應 per-step budget 調控。</li><li><strong>複合 token ranking</strong>：每個 budget 內以 accumulated attention mass + recency 複合分數排名，並設 protected recent window 維持局部 coherence，避免近端 context 被誤刪。</li><li><strong>Mixed-precision 儲存 + 金字塔 layer budget</strong>：結合 FP16/INT8 混合精度儲存與 blockwise online-softmax attention；pyramidal per-layer budget variant 針對不同 layer 深度分配不同 budget。</li><li><strong>端到端效能</strong>：在 Needle-in-a-Haystack（32K tokens）達 91.4% retrieval accuracy，顯著優於 sliding window（53.8%）與 H2O（80.6%）；VisualWebArena 以 2.8× 較低 peak memory 保留 95.3% full-KV success rate。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>四個 model families、生成長度至 4K：KV footprint 接近固定 512-token sliding window，perplexity 僅差 1.5–2.1 points vs full KV。</li><li>Needle-in-a-Haystack（32K）：CONF-KV 91.4% vs sliding window 53.8% vs H2O 80.6%。</li><li>VisualWebArena（75 tasks）：peak memory 降低 2.8×，仍保留 95.3% full-KV success。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文未列明確 limitation 章節。推斷弱點： <ul><li>Confidence score 計算依賴 next-token logit distribution，對採用 sparse softmax 或特殊 head 的模型需額外適配。</li><li>評估 context 長度至 32K；更長序列（128K+）的 confidence score 穩定性未驗證。</li><li>Mixed-precision INT8 quantization 在特定任務（精確數值推理）可能累積誤差，論文未作細分分析。</li></ul></li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>context-management / NLAH 原則直接呼應</strong>：CONF-KV 的核心思想「不確定時保留更多 context、信心高時剪枝」與 core.md 的「Right context &gt; more context」及 context-management.md 的 token budget 軟性控制在概念層高度對齊；CONF-KV 提供了一個可機械驗證的 confidence 信號，而非靜態規則。</li><li><strong>「判斷 vs 決定」跨切紀律</strong>：論文的 confidence score 扮演「LLM 判斷」的量化代理（scalar signal），再由確定性的 budget allocation 邏輯做「決定」（evict / retain），與 core.md 判斷 vs 決定分離原則結構吻合；⚠️ 落地門檻：實際整合需能取得 token-level logit，API-only 環境無法直接套用。</li><li><strong>subagent token budget 優化潛力</strong>：長 agentic session（core.md context-management §compact 觸發）的 KV 壓力與 CONF-KV 解決的問題同域；若推理引擎層可整合此 eviction policy，有機會延後 compact 觸發點；⚠️ 目前 Claude API 不暴露 KV 控制介面，屬研究啟發而非直接可用。</li><li><strong>unverified_success 閘門類比</strong>：CONF-KV 的 protected recent window 設計（保護最近 tokens 不被 evict）在概念上類似 core.md 的「unverified_success 閘門」——即使信心高也不貿然丟棄最新狀態，防止局部 coherence 崩壞；此設計原則可遷移至 agent workflow 的 checkpoint 保護策略。</li></ul>',16)])])}const p=t(i,[["render",r]]);export{g as __pageData,p as default};
